<script setup lang="ts">
import { nextTick,onMounted,onUnmounted,ref } from 'vue'
import Icon from './AppIcon.vue'
import { backendApi,type BackendSkill,type SkillDraft } from '../services/backendApi'
import { useBackendStore,errorText } from '../stores/backend'
const props=defineProps<{skill?:BackendSkill}>(),emit=defineEmits<{close:[];saved:[]}>(),backend=useBackendStore()
const form=ref<SkillDraft>({name:props.skill?.name??'',description:props.skill?.description??'',instructions:props.skill?.instructions??'',enabled:props.skill?.enabled??true,revision:props.skill?.revision??0})
const dialog=ref<HTMLElement>(),busy=ref(false),error=ref(''),confirmDelete=ref(false)
let previous:HTMLElement|null=null
function close(){if(!busy.value)emit('close')}
async function save(){busy.value=true;error.value='';try{if(props.skill)await backendApi.updateSkill(props.skill.id,form.value);else await backendApi.createSkill(form.value);await backend.refreshCapabilities();emit('saved')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function remove(){if(!props.skill)return;busy.value=true;error.value='';try{await backendApi.deleteSkill(props.skill.id);await backend.refreshCapabilities();emit('saved')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function key(e:KeyboardEvent){if(e.key==='Escape'){close();return}if(e.key!=='Tab')return;const all=[...(dialog.value?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),textarea:not([disabled])')??[])].filter(n=>n.offsetParent!==null);if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0]?.focus()}}
onMounted(()=>{previous=document.activeElement as HTMLElement;document.addEventListener('keydown',key);nextTick(()=>dialog.value?.querySelector('input')?.focus())})
onUnmounted(()=>{document.removeEventListener('keydown',key);previous?.focus()})
</script>
<template><div class="modal-scrim" @click.self="close"><section ref="dialog" class="upload-dialog skill-editor" role="dialog" aria-modal="true" aria-labelledby="skill-editor-title"><header><div><span class="eyebrow">YOUR RESEARCH METHOD</span><h2 id="skill-editor-title">{{skill?'编辑科研 Skill':'创建科研 Skill'}}</h2></div><button class="icon-button" aria-label="关闭 Skill 编辑器" :disabled="busy" @click="close"><Icon name="X"/></button></header><p class="modal-description">把常用的分析方法保存为指令，在模型对话中重复使用。</p><form @submit.prevent="save" :aria-busy="busy"><div class="form-grid"><label class="full-row">名称<input v-model="form.name" required maxlength="80" placeholder="例如：论文证据检查"/></label><label class="full-row">用途说明<input v-model="form.description" maxlength="600" placeholder="说明什么时候适合使用这个 Skill"/></label><label class="full-row">科研指令<textarea v-model="form.instructions" required rows="10" maxlength="12000" placeholder="写明任务、步骤、输出格式与证据要求。不要写入 API Key 或账户密码。"/><small>{{form.instructions.length}} / 12000 · 指令可指导分析，不会运行脚本或自动获得联网工具。</small></label><label class="full-row checkbox-label"><input v-model="form.enabled" type="checkbox"/>启用此 Skill</label></div><p v-if="error" class="form-error" role="alert">{{error}}</p><div v-if="confirmDelete" class="skill-delete-confirm"><span>删除后将停止新调用，已有任务记录保留。确认删除？</span><button type="button" class="text-button" :disabled="busy" @click="confirmDelete=false">保留</button><button type="button" class="secondary-button" :disabled="busy" @click="remove">确认删除</button></div><div class="settings-form-bottom"><button v-if="skill&&!confirmDelete" type="button" class="text-button" :disabled="busy" @click="confirmDelete=true">删除 Skill</button><span v-else>保存到个人账户</span><button class="primary-button" :disabled="busy"><Icon v-if="busy" name="LoaderCircle" class="spin" :size="15"/>{{busy?'正在保存…':'保存 Skill'}}</button></div></form></section></div></template>
